Skill 1's table reads like max(g(a), h(b)) for two hidden lookups, because low rows repeat one column pattern and high rows are constant. I will check that form and min against each skill's table, and I expect skill 1 to agree closely and the others to be less clear.

```python
import numpy as np
np.set_printoptions(linewidth=240,precision=2,suppress=True,threshold=100000)
W={n:load(n) for n in NAMES}
def silu(x): return x/(1+np.exp(-x))
def fwd(W,X):
    h=silu(X@W["l1.weight"].T+W["l1.bias"])
    h=silu(h@W["l2.weight"].T+W["l2.bias"])
    return h@W["l3.weight"].T+W["l3.bias"]
A,B=np.meshgrid(np.arange(32),np.arange(32),indexing="ij");A=A.ravel();B=B.ravel()
def inp(s):
    X=np.zeros((1024,68));X[np.arange(1024),A]=1;X[np.arange(1024),32+B]=1;X[:,64+s]=1;return X
def readtab(T,kind):
    # read g,h from table quantiles, then one pass of row/col modes
    q=20 if kind=="max" else 80
    g=np.percentile(T,q,axis=1,method="nearest");h=np.percentile(T,q,axis=0,method="nearest")
    op=np.maximum if kind=="max" else np.minimum
    for _ in range(2):
        for a in range(32):
            sc=[(op(v,h)==T[a]).sum() for v in range(8)];g[a]=int(np.argmax(sc))
        for b in range(32):
            sc=[(op(g,v)==T[:,b]).sum() for v in range(8)];h[b]=int(np.argmax(sc))
    return g.astype(int),h.astype(int),float((op.outer(g,h)==T).mean())
for s in range(4):
    T=fwd(W,inp(s)).argmax(1).reshape(32,32)
    for k in ["max","min"]:
        g,h,ag=readtab(T,k)
        print("skill",s,k,"agreement",round(ag,3))
        print(" g","".join(map(str,g)));print(" h","".join(map(str,h)))
