Skill 0 rows look like a clipped sum, skill 3 rows look like a scaled product, and skill 2 has non-monotone rows. I will score a family of two-lookup forms against each table as a reading aid only, and I expect one form per skill to stand out.

```python
import numpy as np
W={n:load(n) for n in NAMES}
def silu(x): return x/(1+np.exp(-x))
def fwd(W,X):
    h=silu(X@W["l1.weight"].T+W["l1.bias"])
    h=silu(h@W["l2.weight"].T+W["l2.bias"])
    return h@W["l3.weight"].T+W["l3.bias"]
A,B=np.meshgrid(np.arange(32),np.arange(32),indexing="ij");A=A.ravel();B=B.ravel()
def inp(s):
    X=np.zeros((1024,68));X[np.arange(1024),A]=1;X[np.arange(1024),32+B]=1;X[:,64+s]=1;return X
V=np.arange(8)
forms={"max":lambda g,h:np.maximum(g,h),"min":lambda g,h:np.minimum(g,h),"clipsum":lambda g,h:np.minimum(7,g+h),
"sum%8":lambda g,h:(g+h)%8,"diff%8":lambda g,h:(g-h)%8,"absdiff":lambda g,h:np.abs(g-h),"xor":lambda g,h:g^h,"and":lambda g,h:g&h,"or":lambda g,h:g|h,
"prod%8":lambda g,h:(g*h)%8,"prod//7":lambda g,h:(g*h)//7,"prod>>3":lambda g,h:(g*h)>>3,"prod>>2":lambda g,h:np.minimum(7,(g*h)>>2),"prod>>1":lambda g,h:np.minimum(7,(g*h)>>1),"clipprod":lambda g,h:np.minimum(7,g*h)}
