        for start in range(4):
            h=T[[0,8,16,24][start]].copy();g=np.zeros(32,int)
            for _ in range(3):
                for a in range(32): g[a]=np.argmax([(f(v,h)==T[a]).sum() for v in V])
                for b in range(32): h[b]=np.argmax([(f(g,v)==T[:,b]).sum() for v in V])
            ag=(np.array([[f(x,y) for y in h] for x in g])==T).mean()
            if ag>best: best=ag;bg,bh=g.copy(),h.copy()
        out[(s,name)]=(round(float(best),3),"".join(map(str,bg)),"".join(map(str,bh)))
    r=sorted([(out[(s,n)][0],n) for n in forms],reverse=True)[:4]
    print("skill",s,r)
    print("  best g",out[(s,r[0][1])][1],"h",out[(s,r[0][1])][2])
